        {"구절":"행 2:23", "연결점":"하나님의 정하신 뜻에 의해 넘겨진 그리스도", "구분":"신약"},
        {"구절":"빌 2:6-8", "연결점":"자기를 비워 종의 형체를 가지신 그리스도", "구분":"신약"},
        {"구절":"계 17:14", "연결점":"어린양이 이방 세력을 이기심", "구분":"신약"}
