    표8_상담적용: [
        {"상황":"자기 정체성이 흔들리는 분", "성경원리":"다니엘과 친구들의 히브리 이름에는 하나님에 대한 신앙고백이 담겨 있었고, 이것이 이방 땅에서의 정체성의 기초가 됨", "실제적용":"나는 하나님의 자녀라는 정체성을 확고히 하라. 세상의 평가가 아닌 하나님의 부르심이 나의 가치를 결정한다"},
        {"상황":"신앙 생활을 혼자 하는 것이 외로운 분", "성경원리":"다니엘에게는 세 명의 신앙 동지가 있었고, 함께 기도하고 함께 결단했다", "실제적용":"소그룹이나 제자 훈련에 참여하여 신앙의 동역자를 찾으라"},
        {"상황":"자녀에게 신앙을 어떻게 전해야 할지 모르는 부모", "성경원리":"네 청년의 부모들은 이름에 하나님의 이름을 담아 신앙을 전수했다. 이 신앙이 이방 땅에서도 아이들을 지켰다", "실제적용":"일상 속에서 자연스럽게 하나님에 대한 이야기를 나누라. 가정이 가장 중요한 신앙 교육의 현장이다"}
    ],
