        {"구분":"정체성 말살의 시도", "내용":"히브리 청년들의 종교적 정체성을 말살하려 함", "그리스도연결":"그리스도인이라는 이름으로 고난받으나 영광 (벧전 4:16, 행 11:26)"},
        {"구분":"이름은 변해도 본질은 불변", "내용":"외적 이름은 바뀌었으나 내적 신앙은 동일", "그리스도연결":"만유 위에 뛰어난 이름을 받으신 그리스도 (빌 2:9, 엡 1:21)"}
