        {"대지":"서론", "내용":"환관장이 거절했다. 여기서 포기하는 것이 보통 사람이다. 그러나 다니엘은 포기하지 않았다. 그는 실무 감독관에게로 갔다. 방법을 바꾼 것이지 결심을 바꾼 것이 아니다. 이것이 지혜로운 믿음의 끈기다", "예화_적용":"방법은 유연하게, 원칙은 확고하게"},
        {"대지":"1대지: 포기하지 않는 끈기 (결심의 유지)", "내용":"환관장의 거절이 다니엘의 결심을 바꾸지 못함. 하나님의 뜻이라고 확신하면 방법을 바꾸어서라도 나아감", "예화_적용":"기도 응답이 안 올 때 기도를 멈추지 말고 방법을 바꾸라"},
        {"대지":"2대지: 대안을 찾는 지혜 (실무적 접근)", "내용":"최고 권위자가 아닌 실무 담당자에게 접근. 때로는 높은 문이 아닌 낮은 문이 열린다", "예화_적용":"큰 문이 닫히면 작은 문을 찾으라. 하나님의 길은 다양하다"},
        {"대지":"3대지: 리더십의 모델 (동료를 위한 대표)", "내용":"다니엘이 네 명을 대표하여 나서서 교섭. 위기 때 나서는 리더의 모습", "예화_적용":"누군가 나서야 할 때 하나님의 부르심에 응답하라"},
        {"대지":"결론", "내용":"다니엘의 이야기는 한 번의 거절로 끝나지 않았다. 12절에서 그는 구체적인 제안을 한다. 믿음은 포기하지 않는 것이고, 지혜는 방법을 바꾸는 것이다. 둘 다 가져야 한다", "예화_적용":"포기하지 않되 방법은 유연하게, 이것이 지혜로운 믿음이다"}
