    표5_매튜헨리: [
        {"영어원문":"Daniel proposed a trial of ten days, a modest request which showed both faith and prudence.", "한국어번역":"다니엘은 열흘의 시험을 제안했으니, 믿음과 분별력을 동시에 보여주는 겸손한 요청이었다.", "핵심통찰":"믿음과 분별력이 결합된 겸손한 요청이 가장 설득력이 있다"},
        {"영어원문":"He was content with pulse and water, showing that those who live by faith need not the dainties of the king's table.", "한국어번역":"그는 채식과 물로 만족했으니, 믿음으로 사는 자는 왕의 진미가 필요 없음을 보여주었다.", "핵심통찰":"하나님을 신뢰하는 자는 세상의 풍요 없이도 만족한다"},
        {"영어원문":"He did not demand but requested, not presumptuously but humbly, and God honoured his humble faith.", "한국어번역":"그는 요구하지 않고 요청했으며, 교만하지 않고 겸손했고, 하나님은 그의 겸손한 믿음을 존귀하게 하셨다.", "핵심통찰":"겸손한 믿음이 하나님의 존귀를 받는다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"열흘만 시험하여 주소서 - 믿음의 도전", "예화_적용":"참된 믿음은 검증을 두려워하지 않는다"},
        {"대지":"서론", "내용":"다니엘은 놀라운 제안을 한다. '시험하여 보소서.' 보통 시험을 피하려 하는데, 다니엘은 오히려 시험을 요청한다. 왜인가? 결과에 대한 확신이 있기 때문이다. 하나님이 자신을 지켜주실 것을 믿기에 검증을 두려워하지 않는다", "예화_적용":"자신의 믿음을 시험대에 올려놓을 수 있는 용기가 있는가"},
        {"대지":"1대지: 시험하여 보소서 (검증을 환영하는 믿음)", "내용":"다니엘은 시험을 회피하지 않고 오히려 제안함. 하나님에 대한 확신이 있는 자는 증명을 두려워하지 않는다", "예화_적용":"말라기 3:10 - 나를 시험하여 보라고 하시는 하나님"},
        {"대지":"2대지: 채식과 물 (단순함의 능력)", "내용":"왕의 진미 대신 채식과 물. 가장 단순한 것으로 하나님의 능력을 보여줌. 풍요가 아닌 하나님의 공급이 진짜 힘", "예화_적용":"적은 것이라도 하나님이 함께하면 충분하다"},
        {"대지":"3대지: 열흘의 지혜 (합리적 제안)", "내용":"너무 짧지도 길지도 않은 적절한 기간. 상대방의 위험을 최소화하면서 결과를 보여줄 수 있는 지혜로운 제안", "예화_적용":"상대방을 배려하는 지혜로운 접근이 설득력을 높인다"},
        {"대지":"결론", "내용":"다니엘의 '시험하여 보소서'는 믿음의 도전장이었다. 결과는? 10일 후 그들은 왕의 진미를 먹은 자들보다 더 건강했다. 하나님을 시험하라는 것이 아니라, 하나님을 신뢰하고 순종할 때 하나님이 결과를 책임지신다는 것이다", "예화_적용":"순종하고 결과는 하나님께 맡기라"}
    ],
