        {"대지":"2대지: 살이 더욱 윤택하여 (전인적 건강)", "내용":"영적 결단이 육체적 건강으로 나타남. 하나님의 축복은 영혼만이 아니라 몸까지 돌보심", "예화_적용":"하나님의 축복은 영혼과 육체를 함께 돌보신다"},
        {"대지":"3대지: 모든 소년보다 나아 보인지라 (세상과의 비교)", "내용":"왕의 진미를 먹은 자들보다 나은 것은 하나님의 방법이 세상의 방법보다 우월함을 증명", "예화_적용":"세상의 최고와 비교해도 하나님의 방법이 더 낫다"},
        {"대지":"결론", "내용":"잠 10:22 - '여호와께서 주시는 복은 근심을 겸하여 주지 아니하시느니라.' 왕의 진미에는 영적 타협이라는 근심이 따르지만, 하나님의 방법에는 참된 평안이 따른다. 적게 보여도 하나님의 축복이 함께하는 것이 진짜 풍요다", "예화_적용":"하나님의 축복 + 적은 것 > 세상의 풍요 + 근심"}
