        {"구분":"채식이 공식적으로 인정됨", "내용":"하나님의 방법이 공식적으로 수용됨", "그리스도연결":"복음이 세상에 선포되어 열방이 받아들임 (행 1:8, 롬 1:16)"},
        {"구분":"지속적 변화", "내용":"일시적 시험이 영구적 변화로", "그리스도연결":"그리스도의 단번 제사로 영원한 구속을 이루심 (히 9:12, 10:14)"}
