    표5_매튜헨리: [
        {"영어원문":"The steward took away their portion of meat and wine, and gave them pulse. The trial had proved Daniel's point beyond doubt.", "한국어번역":"감독관이 진미와 포도주를 제하고 채식을 주었다. 시험이 다니엘의 주장을 의심의 여지없이 증명한 것이다.", "핵심통찰":"하나님의 결과는 의심의 여지가 없다"},
        {"영어원문":"What began as a ten-day experiment became a permanent arrangement, showing that God's blessings are lasting.", "한국어번역":"열흘의 실험으로 시작된 것이 영구적 조치가 되었으니, 하나님의 축복이 지속적임을 보여준다.", "핵심통찰":"하나님의 축복은 일시적이 아니라 지속적이다"},
        {"영어원문":"God rewarded their faithfulness not only with health but with a change of their circumstances.", "한국어번역":"하나님은 그들의 충성에 건강뿐 아니라 환경의 변화로도 보상하셨다.", "핵심통찰":"신실함의 보상은 건강과 환경 모두에 미친다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"진미를 제하고 채식을 주니라 - 승리의 확정", "예화_적용":"한 번의 순종이 지속적 변화를 만든다"},
        {"대지":"서론", "내용":"감독관은 더 이상 시험이 필요 없었다. 결과가 너무 분명했기에 왕의 진미를 아예 제하고 채식을 공식적으로 제공하기 시작했다. 다니엘의 10일 시험이 영구적 변화가 된 것이다", "예화_적용":"작은 순종이 큰 변화의 씨앗이 된다"},
        {"대지":"1대지: 분정된 것을 제하고 (세상의 것이 물러남)", "내용":"왕이 공식적으로 정한 것이 하나님의 결과 앞에서 물러남. 세상의 제도도 하나님의 능력 앞에서 바뀔 수 있다", "예화_적용":"하나님의 능력은 세상의 체계도 변화시킨다"},
        {"대지":"2대지: 채식을 주니라 (하나님의 방법의 승리)", "내용":"채식이 공식적으로 인정됨. 다니엘의 결단이 제도적 변화를 이끌어냄", "예화_적용":"한 사람의 신실한 결단이 환경을 바꿀 수 있다"},
        {"대지":"3대지: 일시적에서 영구적으로 (지속적 변화)", "내용":"10일의 시험이 나머지 3년 전체의 식단으로 확정됨. 일시적 결단이 지속적 변화로 이어짐", "예화_적용":"오늘의 결단이 내일의 습관이 되고, 평생의 삶이 된다"},
        {"대지":"결론", "내용":"다니엘의 이야기에서 배우는 것은 순종의 과정이다. 결단(8절) → 요청(11-12절) → 시험(14절) → 결과(15절) → 확정(16절). 이 과정이 우리의 신앙 성장의 패턴이다. 결단하라, 실행하라, 인내하라, 하나님이 확정하실 것이다", "예화_적용":"결단→실행→인내→확정, 이것이 신앙 성장의 패턴이다"}
    ],
