        {"상황":"환경을 바꾸고 싶은 분", "성경원리":"다니엘은 바벨론의 제도를 직접 바꾸지 않았지만, 자신의 결단과 하나님의 축복으로 환경이 바뀜", "실제적용":"환경을 직접 바꾸려 하지 말고, 자신의 삶부터 바꾸라. 하나님이 환경을 바꿔주신다"}
