        {"대지":"서론", "내용":"3년이 지났다. 15세 전후에 바벨론에 온 청년들이 이제 18세 전후가 되었다. 느부갓네살 대왕 앞에 서는 날이 왔다. 이 3년은 단순한 교육 기간이 아니라 하나님이 그들을 빚으신 시간이었다", "예화_적용":"지금의 준비 기간이 미래의 사명을 위한 하나님의 시간이다"},
        {"대지":"1대지: 기한이 찼으므로 (하나님의 때)", "내용":"모든 준비에는 끝이 있고, 때가 되면 결실의 순간이 온다. 하나님의 때를 인내로 기다린 자에게 기회가 온다", "예화_적용":"지금이 준비의 때라면 조급해하지 말라. 때가 반드시 온다"},
        {"대지":"2대지: 환관장이 데리고 (인도하시는 하나님)", "내용":"처음 다니엘을 염려했던 환관장이 이제 자신있게 왕에게 소개. 하나님의 결과가 사람의 태도를 바꿈", "예화_적용":"하나님의 축복의 결과는 주변 사람도 변화시킨다"},
        {"대지":"3대지: 느부갓네살 앞으로 (사명의 자리)", "내용":"포로 소년이 세계 최강 제국의 왕 앞에 서게 됨. 가장 낮은 곳에서 가장 높은 곳으로 인도하시는 하나님", "예화_적용":"하나님은 낮은 곳에서 신실한 자를 높은 곳에 세우신다"},
        {"대지":"결론", "내용":"다니엘의 여정을 돌아보면: 포로 → 선발 → 결단 → 시험 → 축복 → 왕 앞에 섬. 이 모든 과정이 하나님의 인도하심 아래 있었다. 지금 당신의 과정도 하나님의 인도 안에 있다", "예화_적용":"내 인생의 모든 과정이 하나님의 인도 안에 있음을 신뢰하라"}
