        {"항목":"모든 후보 중 최고", "내용":"바벨론 제국 전역에서 선발된 엘리트 중에서도 이 네 명이 단연 최고였음. 유다뿐 아니라 다른 나라 포로들도 포함된 경쟁에서의 압도적 우위", "목회적활용":"하나님의 은사는 세상의 어떤 기준으로도 비교할 수 없다"},
        {"항목":"왕 앞에 모시게 함", "내용":"'왕 앞에 서다'는 왕의 직속 자문관으로 임명되는 것. 바벨론 제국에서 최고의 지위 중 하나. 포로 신분에서 제국의 핵심 관리로", "목회적활용":"하나님은 가장 낮은 곳의 사람을 가장 높은 곳에 세우실 수 있다"}
