        {"구분":"비교할 자가 없음", "내용":"모든 후보 중 비교 불가의 탁월함", "그리스도연결":"비교할 수 없이 탁월하신 그리스도의 이름 (빌 2:9, 엡 1:21)"},
        {"구분":"낮은 곳에서 높은 곳으로", "내용":"포로에서 제국의 관리로 높여짐", "그리스도연결":"십자가에서 하나님 우편으로 높여지신 그리스도 (행 2:33, 빌 2:9)"}
