    표5_매튜헨리: [
        {"영어원문":"Among them all was found none like Daniel and his three friends. God's scholars excel all others.", "한국어번역":"그들 모두 중에 다니엘과 세 친구 같은 자가 없었다. 하나님의 학생들은 다른 모든 이를 능가한다.", "핵심통찰":"하나님의 학교에서 배운 자가 가장 뛰어나다"},
        {"영어원문":"They were preferred above all, not because of their own merit, but because God had qualified them for the service.", "한국어번역":"그들이 모든 이 위에 뽑힌 것은 자기 공로가 아니라 하나님이 그들을 봉사에 적합하게 하셨기 때문이다.", "핵심통찰":"하나님이 적합하게 하신 자가 선택받는다"},
        {"영어원문":"They stood before the king, fulfilling the purpose for which God had sent them to Babylon.", "한국어번역":"그들이 왕 앞에 서니, 하나님이 그들을 바벨론에 보내신 목적이 성취되었다.", "핵심통찰":"하나님의 목적은 어떤 과정을 거치든 반드시 성취된다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"같은 자가 없으므로 - 구별된 탁월함의 비밀", "예화_적용":"하나님과 함께하는 자는 비교 불가의 탁월함을 보인다"},
        {"대지":"서론", "내용":"바벨론 제국 전역에서 모인 최고의 엘리트들 중에서 네 명의 유다 청년이 단연 최고로 선발되었다. '같은 자가 없었다.' 이 평가의 비밀은 무엇인가? 바벨론 교육이 아니라 하나님의 은사였다", "예화_적용":"세상의 기준으로도 인정받는 신앙인이 되라"},
        {"대지":"1대지: 왕이 직접 면담하여 (최종 검증)", "내용":"최고 권력자 앞에서의 평가를 통과. 하나님이 함께하시면 어떤 면담도 두렵지 않다", "예화_적용":"중요한 면접과 평가 앞에서 하나님의 동행을 신뢰하라"},
        {"대지":"2대지: 같은 자가 없으므로 (비교 불가)", "내용":"수많은 후보 중 압도적 우위. 이것은 인간의 노력만으로는 불가능한 하나님의 은사의 결과", "예화_적용":"하나님의 은사를 받은 자는 세상도 인정할 수밖에 없다"},
        {"대지":"3대지: 왕 앞에 모시게 하고 (최고의 자리)", "내용":"포로에서 왕의 자문관으로. 가장 낮은 곳에서 가장 높은 곳으로 인도하시는 하나님", "예화_적용":"하나님은 자기 뜻대로 사람을 높이시고 낮추신다"},
        {"대지":"결론", "내용":"다니엘 1장의 결론: 음식을 거부한 포로 소년이 제국의 핵심 관리가 되었다. 이것이 순종의 결과이며, 하나님의 높이심의 결과이다. 세상의 기준이 아닌 하나님의 기준으로 살 때, 세상도 인정하는 탁월함이 나타난다", "예화_적용":"하나님의 기준으로 살면 세상의 인정도 따라온다"}
    ],
