        {"영어원문":"From captive youth to aged counsellor, Daniel's life was a testimony to the power of early godly resolution.", "한국어번역":"포로 청년에서 노년의 자문관까지, 다니엘의 생애는 젊은 날의 경건한 결심의 능력에 대한 증거였다.", "핵심통찰":"젊은 날의 경건한 결심이 평생을 지배한다"}
