        {"대지":"결론", "내용":"다니엘 1장은 8절의 결단으로 시작하여 21절의 평생 신실함으로 끝난다. 한 순간의 결단이 평생의 삶을 결정했다. 디모데후서 4:7 - '나는 선한 싸움을 싸우고 나의 달려갈 길을 마치고 믿음을 지켰으니.' 이것이 다니엘의 생애 요약이다", "예화_적용":"인생의 마지막에 '나는 믿음을 지켰다'라고 말할 수 있는 삶을 살자"}
