        {"대지":"서론", "내용":"역사상 가장 강력한 제국들도 결국 사라졌다. 바벨론, 로마, 대영제국... 세상의 모든 영광은 유한하다.", "예화_적용":"역사 속 강대국의 흥망성쇠를 간략히 소개하며 시작."},
        {"대지":"1대지", "내용":"하나님이 주신 영광 - 느부갓네살의 광대한 지배권은 하나님이 주신 것이다.", "예화_적용":"내가 가진 모든 것이 하나님이 주신 것임을 인식하는 감사의 삶."},
        {"대지":"2대지", "내용":"빛나지만 유한한 금 머리 - 금은 가장 귀하지만 신상 전체의 한 부분이다. 세상의 영광은 제한적이다.", "예화_적용":"세상의 성공과 영광에 집착하지 않고 영원한 것을 추구하도록."},
        {"대지":"3대지", "내용":"더 큰 나라를 바라보라 - 신상은 결국 뜨인 돌에 무너진다. 우리는 영원한 하나님 나라를 소망해야 한다.", "예화_적용":"현재의 고난과 세상의 유혹 속에서 하나님 나라를 바라보는 소망."},
        {"대지":"결론", "내용":"세상의 금 머리 같은 영광보다 하나님 나라의 시민권을 더 소중히 여기는 삶을 살자.", "예화_적용":"빌 3:20 — 우리의 시민권은 하늘에 있다."}
