        {"상황":"삶의 화려함이 사라진 후 공허함을 느끼는 성도", "성경원리":"금 머리의 영광은 신상의 한 부분이다. 진정한 충만함은 영원한 하나님 나라에 있다.", "실제적용":"영원한 가치를 추구하는 새로운 목표를 설정하고, 공동체 안에서 의미 있는 섬김을 찾도록 돕는다."}
