        {"항목":"풀무의 구조와 온도", "내용":"바벨론의 풀무는 벽돌 제조나 금속 제련에 사용되었으며, 아구(입구)가 있는 구조였다. 3장 22절에서 7배나 뜨겁게 했다는 것은 상상을 초월하는 열기였다", "목회적활용":"현실적인 위험과 죽음의 위협 앞에서도 하나님을 신뢰하는 믿음을 강조할 때 활용"},
        {"항목":"느부갓네살의 신관", "내용":"당시 신들은 지역적이고 민족적이었다. 이스라엘이 포로로 잡혀온 것은 바벨론 신이 이스라엘 신보다 강하다는 증거로 여겨졌다", "목회적활용":"세상은 성공과 번영으로 하나님의 능력을 측정하지만, 하나님은 위기 속에서 참된 능력을 나타내신다"},
        {"항목":"조건부 신앙의 문제", "내용":"세 청년의 고백에는 '만일 그럴 것이면'이라는 표현이 있어, 이것이 조건부 신앙인지 논의가 있다. 그러나 이어지는 18절이 그 완전한 의미를 밝힌다", "목회적활용":"결과에 관계없이 하나님을 신뢰하는 절대적 신앙의 본질을 가르치는 데 활용"}
