        {"영어원문":"They owned that God could, if he pleased, work a miracle for their preservation.", "한국어번역":"그들은 하나님이 기뻐하신다면 그들을 보존하기 위해 기적을 행하실 수 있음을 인정했다.", "핵심통찰":"기적은 하나님의 주권적 선택이며, 성도는 기적을 요구하는 것이 아니라 하나님의 뜻을 신뢰한다"},
        {"영어원문":"They trusted not in their own merits, but in God's mercy and power.", "한국어번역":"그들은 자신들의 공로가 아니라 하나님의 자비와 능력을 신뢰했다.", "핵심통찰":"구원의 근거는 인간의 의로움이 아니라 하나님의 은혜와 전능하심이다"}
