        {"원어":"פָּלַח (팔라흐)", "의미_문법":"섬기다, 예배하다 - 아람어 동사 페알 미완료형", "설교포인트":"예배와 섬김은 결과에 따른 조건적 행위가 아니라 본질적 신앙의 표현이다"},
        {"원어":"צֶלֶם (첼렘)", "의미_문법":"형상, 신상 - 아람어 명사, 인간이 만든 우상을 지칭", "설교포인트":"인간이 만든 신상은 참된 경배의 대상이 될 수 없음을 분명히 선언한다"},
        {"원어":"סְגִד (세기드)", "의미_문법":"절하다, 경배하다 - 아람어 동사 페알 미완료형", "설교포인트":"외적 형식의 절하기조차 거부한 것은 신앙의 타협 없는 순수성을 보여준다"}
