    표8_상담적용: [
        {"상황":"기도 응답이 없어 신앙을 회의하는 성도", "성경원리":"하나님을 섬기는 것은 응답의 결과가 아니라 하나님 자체에 대한 신뢰다. '그리 아니하실찌라도'의 신앙이 필요하다", "실제적용":"하박국서를 함께 묵상하며, 하나님의 침묵 속에서도 신뢰하는 신앙의 성숙함을 이야기하라"},
        {"상황":"세상의 유혹과 타협의 압박을 느끼는 성도", "성경원리":"세 청년처럼 어떤 압박에도 우상에게 절하지 않는 분명한 선이 필요하다", "실제적용":"성도의 삶에서 구체적인 '절하지 않아야 할 선'이 무엇인지 함께 점검하고 결단하도록 돕는다"},
        {"상황":"고난이 지속되어 하나님의 선하심을 의심하는 성도", "성경원리":"고난이 지속되어도 하나님은 여전히 선하시고 신실하시다. 결과가 아닌 하나님의 성품을 신뢰하라", "실제적용":"욥기를 함께 읽으며 고난의 의미와 하나님의 선하심을 재발견하도록 동행하라"}
    ],
