        {"새찬송가":"364", "통일찬송가":"407", "제목":"내 주를 가까이 하게 함은", "선정이유":"고난 중에도 하나님께 더 가까이 나아가는 신앙의 자세"},
        {"새찬송가":"384", "통일찬송가":"430", "제목":"나 어느 곳에 있든지", "선정이유":"어디에 있든지 하나님이 함께 하심을 고백하는 찬송"},
        {"새찬송가":"491", "통일찬송가":"200", "제목":"하나님의 크신 사랑", "선정이유":"세밀하고 크신 하나님의 사랑과 돌봄을 찬양하는 찬송"}
