    본문내용: "이 세 사람 사드락과 메삭과 아벳느고는 결박된채 극렬히 타는 풀무 가운데 떨어졌더라",
    표1_원어분석: [
        {"원어":"תְּלָתָא גֻּבְרַיָּא (텔라타 구브라야)", "의미_문법":"세 사람 - 아람어 숫자+명사, 공동체적 신앙인들을 명확히 지칭", "설교포인트":"세 사람이 함께 고난에 직면한 것은 혼자가 아닌 공동체로 고난에 서는 것의 중요성을 보여준다"},
        {"원어":"כְּפִיתִין (케피틴)", "의미_문법":"결박된 - 아람어 형용사 복수형, 완전히 묶인 상태", "설교포인트":"결박된 채로 떨어진 것은 완전한 무력함의 상태였지만, 바로 그 무력함이 하나님의 기적의 출발점이다"},
        {"원어":"נְפַלוּ (네팔루)", "의미_문법":"떨어졌다 - 아람어 동사 페알 완료형 3인칭 복수, 투척되어 떨어짐", "설교포인트":"인간의 가장 낮은 곳으로 던져지는 그 순간이 하나님의 구원의 역사가 시작되는 지점이다"},
        {"원어":"גּוֹא אַתּוּן (고 아툰)", "의미_문법":"풀무 가운데 - 아람어 전치사구, 가장 위험한 핵심부를 의미", "설교포인트":"가장 위험한 곳 그 한가운데서 하나님을 만난다. 고난의 한복판이 하나님의 임재의 장소다"}
    ],
    표2_역사적배경: [
        {"항목":"이 절의 간결함의 의미", "내용":"이 절은 매우 간결하게 세 청년이 불 속에 떨어진 사실만을 기록한다. 이 단순한 서술은 독자의 긴장감을 최고조로 높이는 문학적 기법이다", "목회적활용":"때로 하나님은 최악의 상황을 경험하게 하시지만, 그 후에 놀라운 역사를 보여주신다는 것을 가르치는 데 활용"},
        {"항목":"완전한 고난의 경험", "내용":"세 청년은 실제로 불 속에 던져졌다. 하나님은 그들이 그 경험을 피하게 하지 않으셨다. 고난을 통과하게 하시는 하나님의 방법이다", "목회적활용":"하나님이 고난을 완전히 막아주시는 것이 아니라 고난 속에서 함께하신다는 진리를 가르치는 데 활용"},
        {"항목":"고난의 정점", "내용":"이 절은 이야기의 정점이다. 이후 24절부터는 기적과 역전이 시작된다. 고난이 극에 달할 때가 전환점이 되는 성경의 패턴이다", "목회적활용":"고난이 가장 심할 때가 하나님의 역사의 시작임을 격려하는 데 활용"}
    ],
    표3_신학적의미: [
        {"교리":"고난의 신학(Theology of Suffering)", "설명":"하나님은 세 청년이 불을 피하게 하지 않으셨다. 그러나 불 속에서 함께 하셨다. 고난은 피해야 할 것이 아니라 통과해야 할 과정이다", "관련구절":"사 43:2, 시 23:4, 롬 8:17, 빌 3:10"},
        {"교리":"임재의 신학", "설명":"가장 위험한 곳 한가운데서 하나님이 가장 분명하게 임재하셨다. 하나님의 임재는 안전한 곳에만 제한되지 않는다", "관련구절":"시 139:8, 행 7:55-56, 마 28:20, 히 13:5"},
        {"교리":"연대적 고난", "설명":"세 사람이 함께 고난을 당한 것은 성도의 고난이 개인적이면서도 공동체적임을 보여준다. 교회는 함께 고난받는 공동체다", "관련구절":"고전 12:26, 롬 12:15, 히 13:3, 골 1:24"}
    ],
    표4_예표론: [
        {"구분":"예수님의 죽음", "내용":"결박된 채 던져진 세 청년은 십자가에 달린 예수님의 예표다. 하나님은 그 아들도 고난을 통과하게 하셨다", "그리스도연결":"(눅 23:33)"},
        {"구분":"세례의 예표", "내용":"물 속으로 내려가 다시 올라오는 세례처럼, 풀무 속으로 던져졌다가 살아 나오는 것은 죽음과 부활의 예표다", "그리스도연결":"(롬 6:3-4)"},
        {"구분":"고난과 영광의 패턴", "내용":"먼저 고난이 있고 그 후에 영광이 오는 것은 그리스도의 고난과 부활의 패턴을 예표한다", "그리스도연결":"(벧전 1:11)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"They fell into the midst of the burning, fiery furnace — a most terrible situation for any man.", "한국어번역":"그들은 극렬히 타는 풀무 한가운데로 떨어졌다. 어떤 사람에게도 가장 두려운 상황이었다.", "핵심통찰":"하나님은 때로 성도들이 가장 두려운 상황을 실제로 경험하게 하신다. 그러나 그 안에서 함께 하신다"},
        {"영어원문":"Notice they fell bound — this is the extremity of their helplessness, yet God was with them in their extremity.", "한국어번역":"그들이 결박된 채로 떨어진 것에 주목하라. 이것은 그들의 무력함의 극단이었다. 그러나 하나님은 그 극한 상황에서 그들과 함께 계셨다.", "핵심통찰":"인간의 가장 무력한 극한 상황이 하나님의 임재를 가장 분명하게 경험하는 자리가 된다"},
        {"영어원문":"The worst that man could do had been done to them. Now it was God's turn.", "한국어번역":"인간이 할 수 있는 최악이 그들에게 행해졌다. 이제는 하나님의 차례였다.", "핵심통찰":"인간이 할 수 있는 모든 것이 다 행해진 후에야 하나님의 역사가 온전히 드러난다. 하나님은 항상 마지막 말씀을 하신다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"불 가운데 던져지다 - 고난의 한복판이 하나님의 임재의 자리다", "예화_적용":"고난이 가장 극심한 그 순간에 하나님이 가장 가까이 계심을 선포하는 설교"},
        {"대지":"서론", "내용":"세 청년은 실제로 불 속에 던져졌다. 하나님은 고난을 막아주지 않으셨다. 그러나 그 불 속으로 함께 들어가셨다. 이것이 하나님의 방법이다", "예화_적용":"암 치료 과정의 고통 속에서 오히려 하나님을 가장 가까이 경험했다는 성도의 간증으로 시작"},
        {"대지":"1대지", "내용":"하나님은 고난을 피하게 하시는 것이 아니라 고난 속에 함께 하신다 - '불 속에 있을 때' 의 하나님", "예화_적용":"시편 23:4 '내가 사망의 음침한 골짜기를 다닐찌라도' - 피하는 것이 아니라 통과하는 것"},
        {"대지":"2대지", "내용":"고난의 극점이 전환점이다 - 불 속에 던져진 그 순간이 기적이 시작되는 순간", "예화_적용":"요셉이 구덩이에 던져진 그 순간이 오히려 이집트 총리가 되는 과정의 시작이었다는 것을 연결"},
        {"대지":"3대지", "내용":"고난은 함께 당한다 - 세 사람이 함께 불 속에 떨어진 것의 공동체적 의미", "예화_적용":"고난받는 형제자매 곁에 함께 서는 것이 교회의 본질임을 구체적인 사례로 적용"},
        {"대지":"결론", "내용":"오늘 당신이 불 속에 있다면, 그 불 속이 하나님을 가장 가까이 만나는 자리임을 기억하라", "예화_적용":"성도들이 현재 자신의 고난을 하나님의 임재의 자리로 재해석하는 기도로 마무리하라"}
    ],
