        {"새찬송가":"377", "통일찬송가":"438", "제목":"어둠 속에 나 홀로 있으나", "선정이유":"고난의 어둠 속에서도 하나님의 임재를 노래하는 찬송"},
        {"새찬송가":"364", "통일찬송가":"407", "제목":"내 주를 가까이 하게 함은", "선정이유":"고난이 오히려 하나님께 더 가까이 가는 계기가 됨을 노래"},
        {"새찬송가":"419", "통일찬송가":"472", "제목":"내 주 되신 주를 참 사랑하고", "선정이유":"고난 중에도 주님을 사랑하는 헌신을 표현하는 찬송"}
