        {"항목":"포로의 고위직 임명", "내용":"포로로 잡혀온 이스라엘 청년들이 바벨론의 고위직에 임명된 것은 당시 바벨론의 실용적 통치 방식을 반영한다. 능력 있는 자를 국적에 관계없이 임용했다", "목회적활용":"하나님은 신앙인들을 세상의 영향력 있는 자리에 세우신다는 것을 가르치는 데 활용"},
        {"항목":"'더욱 높이니라'의 의미", "내용":"풀무 사건 이전에도 세 청년은 이미 직위에 있었다(2:49). '더욱 높이니라'는 것은 그 이전보다 더 높은 자리로 올라간 것을 의미한다", "목회적활용":"고난을 통과한 후 하나님이 더 큰 영향력의 자리로 이끄신다는 섭리를 가르치는 데 활용"},
        {"항목":"이야기의 마무리 구조", "내용":"이 절은 3장 전체의 결론이다. 시련 → 신앙 고백 → 위기 → 기적 → 찬송 → 높아짐이라는 패턴은 성경 전체의 구속 서사 구조와 일치한다", "목회적활용":"성경의 구속 역사 패턴을 이 절을 통해 가르치는 데 활용"}
