    표3_신학적의미: [
        {"교리":"고난 후의 영광(후에 영광)", "설명":"먼저 고난이 있고 그 후에 영광이 오는 패턴은 성경 전체의 구속 신학의 핵심이다. 세 청년의 이야기가 이 패턴의 완전한 예시다", "관련구절":"롬 8:17, 벧전 1:11, 히 12:2, 고후 4:17"},
        {"교리":"신앙의 보상(Reward)", "설명":"하나님을 신뢰하고 고난을 견딘 자들이 더욱 높임을 받은 것은 신앙의 순종에 따른 보상이다. 이것은 공로가 아닌 은혜로운 상급이다", "관련구절":"마 5:11-12, 히 11:26, 계 2:10, 롬 8:18"},
        {"교리":"하나님의 나라와 세상 나라의 역설", "설명":"세상에서 가장 낮아진 포로들이 세상 제국의 중심에서 가장 높아진다. 하나님의 나라 논리는 세상 나라 논리를 역전시킨다", "관련구절":"마 5:3-12, 눅 1:52-53, 고전 1:27-28, 약 2:5"}
    ],
