        {"대지":"서론", "내용":"포로로 끌려온 청년들이 죽음의 위협을 통과하고 마침내 바벨론 제국에서 더욱 높아졌다. 이 결말이 우리에게 주는 소망은 무엇인가?", "예화_적용":"감옥에서 나와 더 큰 지도자가 된 요셉의 이야기와 연결하여 하나님의 역전의 패턴을 소개"},
        {"대지":"1대지", "내용":"하나님은 고난 후에 더욱 높이신다 - '더욱 높이니라'의 의미", "예화_적용":"성경의 고난 후 영광의 패턴들(요셉, 다윗, 욥, 바울)을 열거하여 이것이 성경의 일관된 패턴임을 보여라"},
        {"대지":"2대지", "내용":"고난을 통과한 자가 더 큰 영향력을 얻는다 - 포로가 바벨론 도의 통치자가 됨", "예화_적용":"고난을 통과하여 더 깊은 목회자, 상담자, 리더가 된 사람들의 실제 사례를 나누라"},
        {"대지":"3대지", "내용":"개인의 높아짐은 하나님의 영광을 위한 것이다 - 세 청년의 높아짐이 바벨론 전체에 미친 영향", "예화_적용":"성도가 세상에서 영향력 있는 자리에 서는 것이 세상을 향한 하나님의 전략임을 가르치라"},
        {"대지":"결론", "내용":"지금 당신이 통과하는 고난의 풀무가 바로 '드디어 높아지는' 날을 향한 하나님의 과정이다. 포기하지 말라", "예화_적용":"성도들이 자신의 고난이 하나님의 영광의 과정임을 고백하는 헌신 기도로 마무리하라"}
