        {"상황":"신앙 때문에 손해를 보고 있다고 느끼는 성도", "성경원리":"세 청년은 신앙 때문에 죽을 뻔했지만 결국 더욱 높아졌다. 신앙의 손해는 하나님의 이익으로 역전된다", "실제적용":"단기적 손해와 장기적 보상의 관점으로 신앙의 열매를 바라보도록 돕고 히브리서 11장을 함께 묵상하라"},
        {"상황":"세상에서의 영향력을 원하지만 신앙과의 충돌을 경험하는 성도", "성경원리":"세 청년이 신앙 때문에 죽음의 위기를 겪었지만 오히려 세상에서 더 큰 영향력을 얻었다. 신앙의 일관성이 세상의 영향력과 대립하지 않는다", "실제적용":"직장이나 사회에서 신앙적으로 일관되게 살면서도 영향력을 가지는 구체적인 방법을 함께 찾아라"}
