        {"교리":"은혜에 의한 변화", "설명":"교만한 이방 왕이 하나님의 이적을 경험하고 공개 선포자가 됨은 하나님의 변화시키는 은혜를 보여줌", "관련구절":"롬 5:20; 엡 2:4-5; 딛 3:5; 고후 5:17"},
        {"교리":"증거의 책임", "설명":"경험한 하나님의 역사를 공개적으로 선포하는 것은 신앙인의 마땅한 책임임", "관련구절":"시 66:16; 행 1:8; 눅 8:39; 마 28:19"}
