        {"원어":"מִשְׁכְּבִי (미쉬케비)", "의미_문법":"내 침상 위에서 - 아람어 명사 1인칭 소유격, 개인적 공간", "설교포인트":"하나님은 가장 개인적인 공간에서도 말씀하심"}
