        {"항목":"침상에서의 계시", "내용":"단 2장의 꿈과 마찬가지로 이 꿈도 침상에서 주어짐. 이는 인간이 의식적 방어를 내려놓는 순간 하나님이 말씀하심을 보여줌", "목회적활용":"하나님은 우리가 하나님의 목소리에 열려있는 고요한 시간에 말씀하심"}
