        {"대지":"서론", "내용":"우리는 두려움을 부정적으로 생각하지만, 때로 두려움은 우리를 구하는 하나님의 은혜입니다. 가장 형통한 왕에게 찾아온 밤의 꿈이 그의 인생을 바꾸었습니다.", "예화_적용":"자동차 경고등이 귀찮게 느껴지지만 실제로 큰 사고를 방지해주듯, 하나님의 경고도 불편하지만 생명을 구하는 은혜임"},
        {"대지":"1대지", "내용":"하나님은 꿈과 이상으로 말씀하신다 - 고대의 왕도 현대의 우리도 하나님의 음성에 귀를 기울여야 함", "예화_적용":"매일 아침 말씀 묵상을 통해 하나님의 음성에 귀를 여는 실천"},
        {"대지":"2대지", "내용":"두려움은 영적 각성의 시작이다 - 왕의 두려움이 그를 도움을 구하게 만들었음. 두려움을 하나님께 나아가는 계기로 삼아야 함", "예화_적용":"인생의 두려운 순간들을 하나님께 기도로 가져가는 실천의 중요성"},
        {"대지":"3대지", "내용":"편안한 때에도 하나님의 말씀에 깨어있어라 - 침상의 꿈처럼 하나님은 고요한 때에 말씀하심", "예화_적용":"바쁜 일상에서 벗어나 고요한 시간(QT, 침묵 기도)을 만들어 하나님의 음성을 듣는 훈련"},
        {"대지":"결론", "내용":"하나님의 경고에 귀를 닫지 마십시오. 두려움도, 불편함도, 양심의 가책도 모두 우리를 더 나은 길로 인도하시는 하나님의 은혜일 수 있습니다.", "예화_적용":"오늘 마음에 불편함이나 두려움을 느끼는 영역에 대해 기도하고 하나님의 메시지를 구하는 실천"}
