        {"구절":"암 3:7", "연결점":"주 여호와께서는 자기의 비밀을 그 종 선지자들에게 보이지 아니하시고는 결코 행하심이 없으시리라 - 행동 전 경고를 주시는 하나님", "구분":"구약"},
        {"구절":"단 2:1", "연결점":"느부갓네살이 왕위에 오른 지 이 년에 꿈을 꾸고 마음이 번민하여 잠을 이루지 못한지라 - 이전 꿈 경험과의 패턴 반복", "구분":"구약"},
        {"구절":"행 2:17", "연결점":"내가 내 영을 모든 육체에 부어 주리니 너희의 자녀들은 예언할 것이요 너희의 늙은이들은 꿈을 꾸며 - 꿈과 이상을 통한 성령의 역사", "구분":"신약"},
        {"구절":"행 2:37", "연결점":"그들이 이 말을 듣고 마음에 찔려 - 하나님의 메시지 앞에서 두려워하는 반응이 회심의 시작", "구분":"신약"},
        {"구절":"계 3:20", "연결점":"내가 문 밖에 서서 두드리노니 누구든지 내 음성을 듣고 문을 열면 내가 그에게로 들어가 그와 더불어 먹고 - 하나님의 개인적인 접근", "구분":"신약"},
        {"구절":"히 12:28", "연결점":"그러므로 우리가 흔들리지 않는 나라를 받았은즉 은혜를 받자 이로 말미암아 경건함과 두려움으로 하나님을 기쁘시게 섬길지니 - 두려움이 경건의 기초가 됨", "구분":"신약"}
