        {"항목":"느부갓네살의 신학적 혼합주의", "내용":"느부갓네살은 '거룩한 신들의 영'이라는 표현을 사용함으로써 다니엘의 하나님을 자신의 다신론 체계에 편입하려 함. 이는 이방인의 자연스러운 종교적 이해 방식임", "목회적활용":"세상은 하나님을 자신들의 체계로 축소하려 함. 하나님의 유일성을 선명히 증거해야 함"},
        {"항목":"다니엘의 공적 신앙 증거", "내용":"다니엘은 이방 왕궁에서도 하나님의 영이 있는 자로 인정받았음. 이는 일관된 신앙 생활의 결과임", "목회적활용":"일상에서의 신앙적 삶이 결국 세상 사람들에게 하나님의 임재를 증거함"}
