        {"교리":"번성의 사회적 책임", "설명":"하나님이 주신 번성은 자신만을 위한 것이 아니라 다른 이들을 섬기기 위한 것. 이 책임을 망각하는 것이 교만의 본질임", "관련구절":"눅 12:48; 레 25:35; 신 15:11; 갈 6:10"},
        {"교리":"하나님의 공급하심", "설명":"모든 생명체가 나무에서 먹을 것을 얻는 이미지는 하나님이 온 세상 생명을 공급하시는 섭리를 반영함", "관련구절":"시 104:27-28; 마 6:26; 행 14:17; 시 145:15-16"}
