        {"대지":"서론", "내용":"번성 자체는 죄가 아닙니다. 느부갓네살의 나무도 처음에는 아름답고 모든 이에게 유익했습니다. 문제는 그 번성의 주인이 누구인가 하는 것입니다.", "예화_적용":"풍성한 자연이 모든 생명을 먹이는 하나님의 창조 설계를 묵상하게 함"},
        {"대지":"1대지", "내용":"번성은 하나님의 선물이다 - 아름다운 잎사귀와 풍성한 열매는 하나님이 주신 것", "예화_적용":"내 재능, 건강, 재물, 관계 중 내가 스스로 만들어낸 것은 하나도 없음을 겸손히 인식하는 훈련"},
        {"대지":"2대지", "내용":"번성은 나누기 위한 것이다 - 만인의 식물, 모든 육체의 먹을거리가 되는 것이 번성의 목적", "예화_적용":"받은 것을 나누는 삶의 실천: 시간, 재물, 재능, 관계를 타인을 위해 사용하는 구체적 방법들"},
        {"대지":"3대지", "내용":"번성의 영광을 하나님께 돌려라 - 모든 것을 제공하는 나무의 번성이 실제로는 하나님의 공급하심임을 인정해야 함", "예화_적용":"성공했을 때 첫 번째 반응이 자랑이 아닌 감사와 헌신이 되는 삶의 훈련"},
        {"대지":"결론", "내용":"하나님이 주신 번성을 하나님께 감사하고, 그 번성을 모든 이와 나누는 청지기의 삶을 사십시오. 이것이 번성의 참된 의미입니다.", "예화_적용":"이번 주 내가 받은 것 중 한 가지를 타인과 나누는 구체적 실천 결단"}
