        {"상황":"번성을 혼자 누리려 하는 성도", "성경원리":"나무의 번성이 모든 생명에게 유익이 된 것처럼, 하나님의 청지기는 받은 것을 나누어야 함(눅 12:48)", "실제적용":"나눔의 영역(헌금, 봉사, 재능 기부 등)을 늘리는 구체적 실천 방안을 함께 계획하기"},
        {"상황":"경제적 어려움으로 하나님의 사랑을 의심하는 성도", "성경원리":"하나님은 모든 육체를 먹이시는 분임(시 145:15-16). 어려운 때에도 하나님의 공급하심을 신뢰해야 함", "실제적용":"과거 하나님의 공급하심의 사례를 정리하고, 현재의 필요를 하나님께 맡기는 기도로 인도"}
