        {"새찬송가":"279", "통일찬송가":"279", "제목":"죄에서 자유를 얻게 함은", "선정이유":"죄와 교만이 제거되는 하나님의 구원의 내용이 본문과 연결"},
        {"새찬송가":"507", "통일찬송가":"507", "제목":"내 주의 보혈은", "선정이유":"죄의 완전한 제거와 새로운 출발을 가능하게 하는 그리스도의 피의 능력"},
        {"새찬송가":"460", "통일찬송가":"460", "제목":"예수 십자가에 흘린 피로써", "선정이유":"심판과 자비가 만나는 십자가의 은혜를 노래하는 내용"}
