        {"상황":"자신의 능력에 과도하게 자신감을 갖고 하나님을 의지하지 않는 경우", "성경원리":"사람이 마음으로 자기의 길을 계획할지라도 그의 걸음을 인도하시는 이는 여호와시니라 (잠 16:9)", "실제적용":"매 결정마다 기도하는 훈련, 자신의 계획을 하나님 앞에 내려놓는 연습"},
        {"상황":"교회나 사역에서 자신의 역할을 과도하게 강조하는 경우", "성경원리":"심는 이나 물 주는 이는 아무 것도 아니로되 오직 자라게 하시는 이는 하나님이시니라 (고전 3:7)", "실제적용":"자신의 역할을 하나님의 도구로 이해하고 다른 사람들의 기여도 인정하는 훈련"}
