        {"대지":"서론", "내용":"가장 화려한 연회 자리에서 갑자기 글씨가 나타났다(단 5장). 자신의 업적을 자랑하는 말이 입에 있을 때 하늘에서 소리가 들렸다(단 4장). 하나님의 심판은 예고 없이 온다.", "예화_적용":"삶의 절정에서 갑자기 무너진 사람들의 이야기"},
        {"대지":"1대지", "내용":"말이 입에 있을 때 - 심판의 즉각성 (31a절) - 교만의 말이 끝나기도 전에 심판이 임했다. 하나님의 심판은 인간의 예상보다 빠를 수 있다.", "예화_적용":"눅 12:20 - '어리석은 자여 오늘 밤에 네 영혼을 도로 찾으리니'"},
        {"대지":"2대지", "내용":"하늘에서 소리가 - 하나님의 직접 개입 (31b절) - 하나님은 먼 곳에 계신 분이 아니다. 역사 속에 직접 개입하시는 실재하는 하나님이시다.", "예화_적용":"다메섹 도상의 바울에게 임한 하나님의 음성 (행 9:4)"},
        {"대지":"3대지", "내용":"나라의 위가 네게서 떠났다 - 주신 것을 거두신다 (31c절) - 하나님이 주신 것은 하나님이 거두실 수 있다. 이것은 공포가 아니라 하나님의 주권에 대한 경외이다.", "예화_적용":"사울 왕에게서 왕권이 떠난 사건과 다윗으로의 이전 (삼상 15:28)"},
        {"대지":"결론", "내용":"우리의 말, 생각, 행동이 하나님 앞에 노출되어 있다. '이 말이 입에 있을 때'처럼 하나님은 우리의 모든 것을 보고 들으신다. 이 의식이 경외와 겸손으로 이어지게 하자.", "예화_적용":"하나님 앞에서 산다는 것의 의미를 삶 속에서 실천하기"}
