        {"항목":"바벨론 멸망 당일의 잔치", "내용":"고대 역사가 헤로도토스와 크세노폰은 바벨론이 함락되던 날 밤 성 안에서 큰 잔치가 열렸다고 기록한다.", "목회적활용":"세상의 안락함이 안전을 보장하지 않는다는 경고로 사용할 수 있다"},
        {"항목":"고레스의 바벨론 공략", "내용":"기원전 539년 고레스는 유프라테스 강 물줄기를 돌려 성벽 아래 수로로 군대를 진입시켜 바벨론을 무혈 점령했다.", "목회적활용":"하나님의 심판은 예상치 못한 방법으로 찾아온다는 것을 가르칠 수 있다"}
