        {"상황":"쾌락과 향락에 빠진 젊은이", "성경원리":"청년이여 네 어린 때를 즐거워하라 그러나 이 모든 일로 인하여 하나님이 너를 심판하실 줄 알라(전 11:9)", "실제적용":"현재의 즐거움이 영원한 심판 앞에서는 무의미함을 깨닫도록 돕기"},
        {"상황":"영적 무감각에 빠진 지도자", "성경원리":"네가 이같이 미지근하여 뜨겁지도 아니하고 차지도 아니하니 내 입에서 너를 토하여 버리리라(계 3:16)", "실제적용":"정기적 자기 점검과 영적 성찰의 시간을 갖도록 구체적 계획 수립을 돕기"}
