        {"대지":"1대지", "내용":"우상의 재료들 - 금, 은, 동, 철, 나무, 돌은 모두 하나님이 만드신 것", "예화_적용":"현대의 우상들(돈, 권력, 쾌락, 명성, 건강, 안락함)도 하나님이 주신 선물을 왜곡한 것"},
        {"대지":"2대지", "내용":"우상의 무능함 - 보지도 듣지도 알지도 못하는 신들", "예화_적용":"사람들이 의지하는 것들(재물, 지위, 인맥)이 결정적 순간에 도움이 되지 않는 경험들"},
        {"대지":"3대지", "내용":"참 하나님만이 찬양받으실 분 - 여호와만이 살아계신 하나님이시다", "예화_적용":"역사 속에서 하나님만이 변하지 않으시고 응답하신다는 구체적 간증"},
        {"대지":"결론", "내용":"당신이 매일 찬양하는 것이 무엇인지 확인하라. 참 하나님만을 경배하라.", "예화_적용":"매일 아침 첫 번째로 향하는 것(폰인지, 하나님인지)이 실제 경배의 대상이다"}
