        {"상황":"지도자 역할로 인한 과중한 스트레스를 받는 성도", "성경원리":"수고하고 무거운 짐진 자들아 다 내게로 오라 내가 너희를 쉬게 하리라(마 11:28)", "실제적용":"하나님 앞에 짐을 내려놓는 구체적 기도 방법과 안식 찾기"},
        {"상황":"잘못된 선택 후 번민하는 성도", "성경원리":"하나님의 뜻대로 하는 근심은 후회 없는 구원에 이르는 회개를 이루고(고후 7:10)", "실제적용":"번민이 회개로, 회개가 회복으로 이어지는 과정을 함께 밟도록 안내하기"}
