        {"원어":"הַנְתָּה דָנִיֵּאל (한타 다니옐)", "의미_문법":"네가 그 다니엘이냐 - 동사+고유명사", "설교포인트":"'그 다니엘'이라는 표현은 다니엘의 명성이 이미 알려져 있었음을 보여준다"}
