        {"항목":"왕의 확인 질문", "내용":"벨사살은 다니엘을 직접 알지 못했다. 이것은 다니엘이 신왕 체제에서 잊혀졌음을 보여준다. 그러나 그의 명성은 살아있었다.", "목회적활용":"사람의 기억에서 사라져도 하나님의 목적 안에서 우리의 이름은 지워지지 않는다"},
        {"항목":"포로와 왕의 만남", "내용":"포로로 잡혀온 유다 자손이 세계 최강 제국의 왕 앞에 서는 장면은 하나님의 주권적 섭리를 보여준다.", "목회적활용":"하나님은 낮은 자를 통해 높은 자에게 말씀하신다"}
