        {"원어":"לָא יָכְלִין (라 야클린)", "의미_문법":"능히 할 수 없었다 - 부정+동사", "설교포인트":"'할 수 없음'이 반복된다. 인간의 한계가 하나님의 능력을 위한 공간을 만든다"},
        {"원어":"פִּשְׁרָא (피쉬라)", "의미_문법":"해석 - 명사", "설교포인트":"하나님의 말씀의 해석은 오직 성령을 통해서만 가능하다"}
