        {"항목":"두 번의 실패 보고", "내용":"벨사살은 박사들의 실패를 다니엘에게 직접 말했다. 이것은 다니엘 앞에서 세상 지혜의 한계를 인정하는 것이었다.", "목회적활용":"세상의 모든 방법이 실패할 때 하나님의 사람의 가치가 드러난다"},
        {"항목":"반복된 실패의 의미", "내용":"8절에서 한 번, 15절에서 또 한 번 실패를 언급함으로써 강조 효과를 낸다. 이는 하나님의 계시의 독자성을 부각시킨다.", "목회적활용":"같은 실패를 반복하는 인생에서 하나님께 돌아서야 할 시간임을 깨달아야 한다"},
        {"항목":"다니엘 앞에서의 고백", "내용":"왕이 포로 출신 다니엘 앞에서 바벨론 최고의 지식인들의 실패를 고백하는 것은 겸손의 시작이다. 그러나 진정한 회개로는 이어지지 않았다.", "목회적활용":"지식의 무릎을 꿇는 것만으로는 충분하지 않다. 영적 회개가 필요하다"}
