    표5_매튜헨리: [
        {"영어원문":"He tells him what his magicians and astrologers had attempted and failed, that they could not read the writing, nor make known to him the interpretation.", "한국어번역":"그는 다니엘에게 마법사들과 점성술사들이 시도했으나 실패한 것을 말했다. 그들이 글자를 읽지도 해석을 알게 하지도 못했다고.", "핵심통찰":"인간의 최선의 시도가 실패한 곳에 하나님의 능력이 나타난다"},
        {"영어원문":"The repeated failures of worldly wisdom are meant to show us that we must look for help to a higher source.", "한국어번역":"세상 지혜의 반복된 실패는 우리가 더 높은 근원에서 도움을 구해야 함을 보여주기 위한 것이다.", "핵심통찰":"반복되는 실패는 하나님께로 방향을 전환하라는 신호이다"},
        {"영어원문":"It is good for us to be told of our failures, that we may be humbled and may seek help from God.", "한국어번역":"우리의 실패에 대해 말을 듣는 것은 우리가 겸손해지고 하나님께 도움을 구하게 되므로 우리에게 유익하다.", "핵심통찰":"실패를 인정하는 것이 하나님의 도움을 구하는 첫 걸음이다"}
    ],
