        {"구절":"시 75:6-7", "연결점":"높이는 것이 동쪽에서나 서쪽에서나 광야에서 나오지 아니하고 오직 재판장이신 하나님이 낮추고 높이심", "구분":"구약"},
        {"구절":"잠 8:15-16", "연결점":"나로 말미암아 왕들이 치리하며 방백들이 공의를 세우며 - 지혜(하나님)로부터 모든 권세가 나온다", "구분":"구약"},
        {"구절":"신 8:17-18", "연결점":"내 능력과 내 손의 힘으로 내가 이 재물을 얻었다 말하지 말고 - 능력 자체가 하나님이 주신 것", "구분":"구약"},
        {"구절":"롬 13:1", "연결점":"각 사람은 위에 있는 권세들에게 복종하라 권세는 하나님으로부터 나지 않음이 없나니", "구분":"신약"},
        {"구절":"요 19:11", "연결점":"위에서 주지 아니하셨더라면 나를 해할 권세가 없었으리니 - 모든 권세는 하나님이 허락하신 것", "구분":"신약"},
        {"구절":"고전 4:7", "연결점":"네가 받지 아니한 것이 무엇이냐 받았은즉 어찌하여 받지 아니한 것같이 자랑하느냐", "구분":"신약"},
        {"구절":"약 1:17", "연결점":"온갖 좋은 은사와 온전한 선물이 다 위로부터 빛들의 아버지께로부터 내려오나니", "구분":"신약"}
