        {"대지":"2대지", "내용":"그러나 이 권세는 임의로 사용될 수 없다. 생사를 임의로 결정하는 것은 하나님의 영역을 침범하는 것이다", "예화_적용":"권위를 남용하는 것은 하나님께서 맡겨주신 청지기 직분을 저버리는 것이다"},
        {"대지":"3대지", "내용":"진정한 두려움의 대상은 하나님이시다. 인간 권세에 대한 두려움이 아닌 하나님 경외가 삶의 기초가 되어야 한다", "예화_적용":"마 10:28 몸은 죽여도 영혼은 능히 죽이지 못하는 자들을 두려워하지 말고"},
        {"대지":"결론", "내용":"하나님이 주신 권세는 그분의 목적대로 사용될 때 진정한 권세이다. 우리에게 주어진 모든 권위와 능력을 하나님의 뜻대로 사용하자", "예화_적용":"가정에서의 부모 권위, 직장에서의 리더십도 하나님이 위임하신 것임을 기억하자"}
