        {"상황":"세상적 성공에 집착하는 성도", "성경원리":"다니엘이 셋째 치리자가 된 날 밤 바벨론이 무너진 것처럼, 세상의 지위는 언제든 사라질 수 있다. 영원한 것을 먼저 구하라(마 6:33).", "실제적용":"삶의 우선순위를 재정립하고 하나님의 나라와 의를 먼저 구하는 것이 오히려 더 많은 것을 얻는 길임을 함께 깨닫는다"}
