        {"대지":"서론", "내용":"벨사살은 연회를 즐기다가 그날 밤 죽임을 당했다. 이것이 단순한 역사적 사건인가, 아니면 우리에게 주는 경고인가?", "예화_적용":"눅 12:20 어리석은 부자 비유 - 내 영혼을 오늘 밤 네게서 찾으리니"},
        {"대지":"1대지", "내용":"그날 밤에 - 심판은 예상치 못한 순간에 임한다", "예화_적용":"살전 5:2 주의 날이 밤에 도둑 같이 이를 줄을 너희 자신이 자세히 알리라"},
        {"대지":"2대지", "내용":"갈대아 왕 벨사살이 - 칭호와 권력이 죽음을 막지 못했다", "예화_적용":"왕도, 부자도, 지식인도 하나님의 심판 앞에서는 동등하다. 죽음은 계급을 가리지 않는다"},
        {"대지":"3대지", "내용":"죽임을 당하였고 - 하나님의 심판 선고는 반드시 실행된다", "예화_적용":"메네 메네 데겔 우바르신이 선고된 그날 밤 성취된 것처럼 하나님의 말씀은 반드시 이루어진다"},
        {"대지":"결론", "내용":"우리는 오늘 밤 어떤 상태인가? 하나님의 저울에서 어떻게 보일까? 지금이 회개하고 준비할 때이다", "예화_적용":"고후 6:2 보라 지금은 은혜 받을 만한 때요 보라 지금은 구원의 날이로다"}
